import json
import re
from collections import deque
from pathlib import Path

HEADER_RE = re.compile(r"^\s*\[([^\]]+)\]\s*$")
CHOICE_RE = re.compile(r"^\s*(\d+)\.\s+(.*?)\s*->\s*([^\s]+)\s*$")
LINE_RE = re.compile(r"^\s*([^:]+):\s*(.*?)\s*->\s*([^\s]+)\s*$")


def _escape_dot(text: str) -> str:
    return (
        text.replace("\\", "\\\\")
        .replace("\"", "\\\"")
        .replace("\n", "\\n")
    )


def parse_script(text: str):
    sections = []
    current_id = None
    current_lines = []

    for raw in text.splitlines():
        line = raw.rstrip()
        if not line.strip():
            continue
        header_match = HEADER_RE.match(line)
        if header_match:
            if current_id is not None:
                sections.append((current_id, current_lines))
            current_id = header_match.group(1).strip()
            current_lines = []
            continue
        if current_id is None:
            continue
        current_lines.append(line)

    if current_id is not None:
        sections.append((current_id, current_lines))

    nodes = {}
    node_order = []
    edges = []

    def add_node(node_id, text_value, speaker_value, node_type):
        if node_id in nodes:
            return
        nodes[node_id] = {
            "id": node_id,
            "text": text_value,
            "speaker": speaker_value,
            "type": node_type,
        }
        node_order.append(node_id)

    for section_id, lines in sections:
        choices = []
        non_choice = []
        for line in lines:
            choice_match = CHOICE_RE.match(line)
            if choice_match:
                choices.append(
                    (
                        choice_match.group(1),
                        choice_match.group(2).strip(),
                        choice_match.group(3).strip(),
                    )
                )
            else:
                non_choice.append(line)

        if choices:
            speaker = ""
            text_parts = []
            for line in non_choice:
                line_match = LINE_RE.match(line)
                if line_match:
                    if not speaker:
                        speaker = line_match.group(1).strip()
                    segment = line_match.group(2).strip()
                    if segment:
                        text_parts.append(segment)
                else:
                    cleaned = line.strip()
                    if cleaned:
                        text_parts.append(cleaned)
            add_node(section_id, " ".join(text_parts).strip(), speaker, "choice")
            for _, choice_text, target in choices:
                edges.append({"from": section_id, "to": target, "text": choice_text})
        else:
            speaker = ""
            text_parts = []
            target = None
            for line in non_choice:
                line_match = LINE_RE.match(line)
                if line_match:
                    if not speaker:
                        speaker = line_match.group(1).strip()
                    segment = line_match.group(2).strip()
                    if segment:
                        text_parts.append(segment)
                    if target is None:
                        target = line_match.group(3).strip()
                else:
                    cleaned = line.strip()
                    if cleaned:
                        text_parts.append(cleaned)
            add_node(section_id, " ".join(text_parts).strip(), speaker, "line")
            if target:
                edges.append({"from": section_id, "to": target, "text": ""})

    # Add missing target nodes (e.g., End) as empty line nodes.
    for edge in edges:
        target = edge["to"]
        if target not in nodes:
            add_node(target, "", "", "line")

    # Enforce reachability from the first node.
    if node_order:
        start = node_order[0]
        adjacency = {node_id: [] for node_id in nodes}
        for edge in edges:
            if edge["from"] in adjacency:
                adjacency[edge["from"]].append(edge["to"])

        reachable = set()
        queue = deque([start])
        while queue:
            current = queue.popleft()
            if current in reachable:
                continue
            reachable.add(current)
            for nxt in adjacency.get(current, []):
                if nxt not in reachable:
                    queue.append(nxt)

        if reachable != set(nodes.keys()):
            nodes = {node_id: nodes[node_id] for node_id in node_order if node_id in reachable}
            node_order = [node_id for node_id in node_order if node_id in nodes]
            edges = [
                edge
                for edge in edges
                if edge["from"] in nodes and edge["to"] in nodes
            ]

    return {
        "nodes": [nodes[node_id] for node_id in node_order],
        "edges": edges,
    }


def _write_outputs(graph, json_path: Path, dot_path: Path):
    json_path.write_text(json.dumps(graph, indent=2), encoding="utf-8")

    lines = ["digraph Dialogue {", "  rankdir=LR;", "  node [shape=box, fontname=\"Helvetica\"];" ]

    for node in graph["nodes"]:
        label_parts = [node["id"], f"[{node['type']}]" ]
        if node["speaker"] or node["text"]:
            if node["speaker"] and node["text"]:
                label_parts.append(f"{node['speaker']}: {node['text']}")
            else:
                label_parts.append(node["text"])
        label = _escape_dot("\\n".join(label_parts))
        lines.append(f"  \"{_escape_dot(node['id'])}\" [label=\"{label}\"];" )

    for edge in graph["edges"]:
        if edge["text"]:
            label = _escape_dot(edge["text"])
            lines.append(
                f"  \"{_escape_dot(edge['from'])}\" -> \"{_escape_dot(edge['to'])}\" [label=\"{label}\"];"
            )
        else:
            lines.append(
                f"  \"{_escape_dot(edge['from'])}\" -> \"{_escape_dot(edge['to'])}\";"
            )

    lines.append("}")
    dot_path.write_text("\n".join(lines), encoding="utf-8")


def main():
    base = Path("/app")
    script_path = base / "script.txt"
    json_path = base / "dialogue.json"
    dot_path = base / "dialogue.dot"

    text = script_path.read_text(encoding="utf-8")
    graph = parse_script(text)
    _write_outputs(graph, json_path, dot_path)


if __name__ == "__main__":
    main()
